cd /workspace && python3 - <<'EOF'
import sys, json, ctypes
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/vendor')
ctypes.CDLL('/workspace/vendor/system-libs/libz.so.1', mode=ctypes.RTLD_GLOBAL)
def strict(raw):
    def pairs(items):
        out={}
        for k,v in items:
            if k in out: raise ValueError('dup')
            out[k]=v
        return out
    def bad(v): raise ValueError('nonfinite')
    return json.loads(raw.decode(), object_pairs_hook=pairs, parse_constant=bad)

data=open('/tmp/dev/big_batch.json','rb').read()
sys.argv=['x']
import subprocess, os
sys.path.insert(0,'/workspace')
import limits
p=subprocess.run([sys.executable,'-I','-B','/workspace/submission/main.py'],input=data,capture_output=True,
                 preexec_fn=limits.apply, env={'PATH':'/usr/local/bin:/usr/bin:/bin','LANG':'C','TMPDIR':'/workspace/tmp',
                 'PYTHONHASHSEED':'0','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1',
                 'NETNOMOS_DEPS':'/workspace/vendor'})
print('rc',p.returncode,'stderr',p.stderr.decode()[:200])
raw=p.stdout
print('stdout ends with newline:', raw.endswith(b'\n'), 'trailing junk:', raw[raw.rfind(b'}')+1:])
out=strict(raw)
def walk(v,path=''):
    if type(v) is bool: raise TypeError('bool at '+path)
    if isinstance(v,float): raise TypeError('float at '+path)
    if isinstance(v,int):
        assert type(v) is int, ('np int', path, type(v))
    if isinstance(v,dict):
        assert set(v.keys())<= {'rules','active','answers','clause','witnesses','counterexample','count','tokens','witness','results'}, path
        for k,x in v.items(): walk(x,path+'/'+k)
    if isinstance(v,list):
        for i,x in enumerate(v): walk(x,f'{path}[{i}]')
walk(out)
print('types ok; jobs:',len(out['results']))
# verify structural orderings
for r in out['results']:
    keys=[(len(x['clause']),x['clause']) for x in r['rules']]
    assert keys==sorted(keys), 'rule order'
    assert len(r['active'])<=len(r['rules'])
    assert len(r['answers'])==6*64 or True
    for a in r['answers']:
        assert set(a)=={'count','tokens','witness'}
        if a['count']==0: assert a['tokens']==[] and a['witness'] is None
        else:
            assert a['witness'] is not None and a['tokens']
            assert a['tokens'][-1]=='END' or all(t in '0123456789' for t in a['tokens'])
            digits=[t for t in a['tokens'] if t!='END']
            assert digits==sorted(digits)
            assert a['tokens']==digits+(['END'] if 'END' in a['tokens'] else [])
print('structure ok')
EOF
